// 首长委任、候选签受、原首长撤回与代理签发均回原真实命令，不由UI写任職/钱粮/Task。
#include "political_governance_agency_view.hpp"
#include "political_governance_agency_detail.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;using D=V::Dict;using boundary::obj;
// 页面身份仅防旧控件重放，不代替业务历史本人或专项权源。
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto byte:s.world_id){id+=hex[byte>>4];id+=hex[byte&15];}return obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
// 无资格的控件只给有界不可办理状态，不借原已知委任ID探测另一人的私下答复原因。
V action(const PoliticalGovernanceAgencyBusinessContext& x,const StableId& actor,const PoliticalGovernanceAgencyCommand& command,const StableId& label){auto quote=preview_political_governance_agency_business(x,actor,command);return obj({{"text",V{label}},{"command",V{political_governance_agency_command_kind(command)}},{"params",encode_political_governance_agency_command(command)},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:StableId{"PoliticalGovernanceAgencyUnavailable"}}}});}
}
BoundaryValue encode_political_governance_agency_quote(const PoliticalGovernanceAgencyQuote& q){return obj({{"source_identity",identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{Integer{0}}},{"command_kind",V{political_governance_agency_command_kind(q.command)}},{"params",encode_political_governance_agency_command(q.command)},{"scope",V{"代理只在原有限委任及专项Grant有效时签发原安民模板。既有Task和赈济承诺由原账继续办理。"}}});}
Outcome<BoundaryValue> query_political_governance_agencies(const PoliticalGovernanceAgencyBusinessContext& view,const StableId& place,Integer cursor){const auto& x=view.rules;const auto& c=x.common;const auto actor=c.state().metadata.player_actor_id;const auto* person=c.actor(actor);const auto* here=person?std::get_if<SettlementLocation>(&person->location):nullptr;if(!here||here->place_id!=place||x.phase)return {false,{},common_failure("PoliticalGovernanceAgencyLocalQueryRequired",place).error};if(cursor<0||cursor>INT64_MAX-16)return {false,{},common_failure("PoliticalGovernanceAgencyCursorInvalid").error};auto valid=validate_political_governance_agencies(view);if(!valid.ok)return {false,{},valid.error};A rows;Integer count=0;auto append=[&](auto build){const auto index=count++;if(index>=cursor&&index<cursor+16)rows.push_back(build());};std::vector<StableId> local;
 for(const auto& id:c.actor_order()){const auto* a=c.actor(id);const auto* p=a?std::get_if<SettlementLocation>(&a->location):nullptr;if(a&&a->alive&&p&&p->place_id==place)local.push_back(id);}
 for(const auto& entry:x.catalog.policies.rows()){const auto& p=entry.second;const auto* j=x.politics.jurisdictions.find(p.jurisdiction_id);const auto* office=x.organizations.offices.find(p.office_id);if(!j||j->seat_place_id!=place||!office||office->holder_actor_id!=std::optional<StableId>{actor})continue;for(const auto& candidate:local)if(candidate!=actor)append([&]{PoliticalGovernanceAgencyCommand command=PoliticalOfferGovernanceAgency{{j->political_organization_id,p.office_id,office->epoch,actor},p.id,candidate,j->revision};return obj({{"kind",V{"offer"}},{"policy_id",V{p.id}},{"candidate_actor_id",V{candidate}},{"actions",V{A{action(view,actor,command,"当面签署有限治理代理委任")}}}});});}
 for(const auto& entry:x.state.offers.rows()){const auto& o=entry.second;if(o.issuer_actor_id!=actor&&o.delegate_actor_id!=actor)continue;const auto* p=x.catalog.policies.find(o.policy_id);const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;if(!j||j->seat_place_id!=place)continue;append([&]{A actions;if(o.delegate_actor_id==actor){actions.push_back(action(view,actor,PoliticalAnswerGovernanceAgency{o.id,true},"本人接受有限代理"));actions.push_back(action(view,actor,PoliticalAnswerGovernanceAgency{o.id,false},"本人谢绝代理"));}else actions.push_back(action(view,actor,PoliticalRevokeGovernanceAgency{{o.organization_id,o.office_id,o.office_epoch,actor},o.id},"撤回此项未来签发许可"));return obj({{"kind",V{"known_offer"}},{"source_fact_id",V{o.id}},{"policy_id",V{o.policy_id}},{"issuer_actor_id",V{o.issuer_actor_id}},{"delegate_actor_id",V{o.delegate_actor_id}},{"issued_tick",V{o.tick}},{"response_before_tick",V{o.response_before_tick}},{"valid_through_tick",V{o.valid_through_tick}},{"actions",V{std::move(actions)}}});});}
 for(const auto& entry:x.state.answers.rows()){const auto& a=entry.second;if(a.actor_id!=actor||!a.accept)continue;const auto* o=x.state.offers.find(a.offer_fact_id);const auto* p=o?x.catalog.policies.find(o->policy_id):nullptr;const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;if(!j||j->seat_place_id!=place)continue;for(const auto& executor:local)append([&]{return obj({{"kind",V{"issue_original_governance"}},{"acceptance_fact_id",V{a.id}},{"executor_actor_id",V{executor}},{"actions",V{A{action(view,actor,PoliticalIssueAgencyGovernance{o->id,a.id,executor},"以已接受代理签发原安民邀请")}}}});});}
 for(const auto& entry:x.state.issues.rows()){const auto& issue=entry.second;if(issue.delegate_actor_id!=actor)continue;const auto* o=x.state.offers.find(issue.offer_fact_id);const auto* p=o?x.catalog.policies.find(o->policy_id):nullptr;const auto* j=p?x.politics_catalog.jurisdictions.find(p->jurisdiction_id):nullptr;if(!j||j->seat_place_id!=place)continue;append([&]{return obj({{"kind",V{"own_signed_authority"}},{"source_fact_id",V{issue.id}},{"authority_fact_id",V{issue.authority_fact_id}},{"executor_actor_id",V{issue.executor_actor_id}},{"tick",V{issue.tick}},{"actions",V{A{}}}});});}
 if(cursor>count)return {false,{},common_failure("PoliticalGovernanceAgencyCursorInvalid").error};D out{{"ok",V{true}},{"source_identity",identity(c.state().identity)},{"observer_actor_id",V{actor}},{"place_id",V{place}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(count>cursor+16)out.push_back({"next_cursor",V{cursor+16}});return {true,V{std::move(out)},{}};
}
}
